<template>
  <v-card
      class="mx-auto cursor-pointer text-center pb-4"
      max-width="350"

  >
    <v-img
        :src="product?.images[0]"
        :alt="`product image ${product?.category.name}`"
        class="zoom-on-hover"
        height="300"
        cover
    >
      <template v-slot:placeholder>
        <v-skeleton-loader height="300" type="image"></v-skeleton-loader>
      </template>
    </v-img>

    <div class="d-flex flex-wrap justify-space-between pl-3 pr-3 pt-4">
      <span class="font-bold"> {{ product?.title }}</span>
      <span class="opacity-70"> {{ product?.category.name }}</span>
    </div>
    <v-card-subtitle class="price"> {{ product?.price }}</v-card-subtitle>

    <v-card-actions class="justify-center">
      <v-btn
          :text="CONTENT.buttonText.addToCart"
          variant="flat"
          :color="colors.primary"
          @click="addToCart($event, product)"
      >
      </v-btn>
    </v-card-actions>
  </v-card>
  <ToastNotification
      v-model="showToastNotif"
      :message="CONTENT.cart.successAdd"
  />
</template>

<script>
// Components
import ToastNotification from "@/components/shared/ToastNotification.vue";

// Static
import STATIC_CONTENT from "@/static/content.json";
import colors from "@/utils/colors.js";

// Vuex
import {createNamespacedHelpers as nameSpace} from "vuex";

const {
  mapActions: cartActions,
} = nameSpace("cartModule");

export default {
  name: "ProductCard",
  props: {
    product: {
      type: Object,
      required: true,
    },
  },
  components: {
    ToastNotification,
  },
  data() {
    return {
      showToastNotif: false,
      colors: colors
    };
  },
  computed: {
    CONTENT() {
      return STATIC_CONTENT;
    }
  },
  methods: {
    ...cartActions([
      "addToCartVuex",
      "setView",
    ]),
    addToCart(event, product) {
      event.stopPropagation(); // Prevents the card click event from firing

      const cart = {
        id: product?.id,
        title: product?.title,
        price: product?.price,
        image: product?.images[0],
        quantity: 1,
      };
      this.addToCartVuex(cart);
      this.setView(false);
      this.showToastNotif = true;
    },
  }
};
</script>