<template>
  <DefaultLayout>
    <v-container class="v-col-9">
      <h2 class="text-h4 font-bold text-center  mt-5">Flitt Demo Shop</h2>
      <p class="text font-light text-center mb-6 opacity-80">To test different Flitt Checkout types choose any product and proceed to the a cart.</p>
      <template v-if="!products.isLoading">
        <v-row v-if="products?.data.length > 0">
          <v-col v-for="product in products.data" :key="product.id" cols="12" md="6">
            <ProductCard :product="product"/>
          </v-col>
        </v-row>
      </template>
      <v-skeleton-loader type="card" v-else></v-skeleton-loader>
    </v-container>
  </DefaultLayout>
</template>

<script>
// Components
import DefaultLayout from "@/layouts/DefaultLayout.vue";
import ProductCard from "@/components/products/ProductCard.vue";

// API
import productsApi from "@/api/productsApi.js";

export default {
  name: "HomeView",
  components: {
    DefaultLayout,
    ProductCard,
  },
  data() {
    return {
      products: {
        data: [],
        isLoading: false,
      },
      categories: {
        data: [],
        isLoading: false,
      },
      searchParams: {
        categoryId: null,
        searchInput: null,
      },
    };
  },
  watch: {
    searchParams: {
      handler(newVal, oldVal) {
        // Filter
        this.getAllProducts({
          categoryId: newVal.categoryId || null,
          title: newVal.searchInput || null,
        });
      },
      deep: true,
    }
  },
  async mounted() {
    await this.getAllProducts();
  },
  methods: {
    async getAllProducts(params) {
      try {
        this.products.isLoading = true;
        const response = await productsApi.getAllProducts(params);
        this.products.data = response.data;
        this.products.isLoading = false;

      } catch (error) {
        console.error("HomeView - getAllProducts - Error fetching data:", error);
        this.products.isLoading = false;
      }
    }
  },
};
</script>
